INSERT INTO "news_signals" VALUES(614,'2026-08-13','2026-08-13 14:17','매경 기업','반도체 소부장','호재','삼양엔씨켐','삼양엔씨켐, 상반기 영업익 121억원…전년比 38.0% 증가','AI 반도체 수요 확대 수혜삼양그룹의 반도체 포토레지스트(PR) 소재 전문기업 삼양엔씨켐은 2026년 상반기에 매출 787억원, 영업이익 121억원의 실적을 거뒀다고 13일 밝혔다..','https://www.mk.co.kr/news/business/12126466',1.5);
