BEGIN TRANSACTION;
CREATE TABLE candidates (
    date         TEXT NOT NULL,
    code         TEXT NOT NULL,
    name         TEXT NOT NULL,
    kr_theme     TEXT,
    origin       TEXT NOT NULL,   -- readacross | news | momentum
    tier         TEXT NOT NULL,   -- pick | pool
    reason       TEXT,            -- 통과한 필터 한 줄
    setup        TEXT,            -- 눌림목 | 정배열 돌파 | 과열 | 역배열 ...
    entry        REAL,
    stop         REAL,
    target1      REAL,
    target2      REAL,
    rr           REAL,            -- 손익비
    score        REAL,
    risk_flags   TEXT,
    data_status  TEXT NOT NULL,   -- ok | 차트 확인 필요 | 데이터 부재
    PRIMARY KEY (date, code, origin)
);
CREATE TABLE global_baseline (
    date        TEXT NOT NULL,
    symbol      TEXT NOT NULL,
    label       TEXT,
    close       REAL,
    change_pct  REAL,
    asof        TEXT,             -- 시세 기준시각(현지 마감)
    source      TEXT,
    PRIMARY KEY (date, symbol)
);
CREATE TABLE news_signals (
    id          INTEGER PRIMARY KEY AUTOINCREMENT,
    date        TEXT NOT NULL,
    published   TEXT,
    source      TEXT NOT NULL,    -- 한국경제 | 매일경제 | 연합뉴스 | DART | manual
    kr_theme    TEXT,
    direction   TEXT NOT NULL,    -- 호재 | 악재 | 죽은테마
    stocks      TEXT,             -- 본문에서 잡힌 종목명(콤마 구분)
    title       TEXT NOT NULL,
    summary     TEXT,
    url         TEXT,
    weight      REAL NOT NULL DEFAULT 1.0,
    UNIQUE (date, source, title, kr_theme)
);
CREATE TABLE outcomes (
    date        TEXT NOT NULL,
    code        TEXT NOT NULL,
    horizon     INTEGER NOT NULL, -- 3 | 5 | 10 | 20 거래일
    ret_pct     REAL,
    max_gain    REAL,
    max_draw    REAL,
    hit_stop    INTEGER,
    PRIMARY KEY (date, code, horizon)
);
CREATE TABLE stocks (
    code        TEXT PRIMARY KEY,
    name        TEXT NOT NULL,
    market      TEXT,
    themes      TEXT,             -- 소속 테마(콤마 구분)
    watchlist   INTEGER NOT NULL DEFAULT 0,
    first_seen  TEXT,
    last_seen   TEXT
, surge_days INTEGER, surge_asof TEXT);
CREATE TABLE theme_daily (
    date        TEXT NOT NULL,
    kr_theme    TEXT NOT NULL,
    n_stocks    INTEGER,          -- 그날 이 테마에서 오른 종목 수
    avg_change  REAL,             -- 평균 상승률(%)
    source      TEXT,             -- seed_xlsx | naver_theme
    PRIMARY KEY (date, kr_theme, source)
);
CREATE TABLE themes (
    kr_theme    TEXT PRIMARY KEY,
    us_theme    TEXT,
    track       TEXT NOT NULL DEFAULT 'readacross',  -- readacross | domestic
    keywords    TEXT,                                -- 뉴스 매칭용 키워드(콤마 구분)
    updated_at  TEXT
);
CREATE INDEX idx_news_date  ON news_signals (date);
CREATE INDEX idx_cand_date  ON candidates (date);
CREATE INDEX idx_theme_date ON theme_daily (date);
DELETE FROM "sqlite_sequence";
COMMIT;